int main(int argc,char**argv){constexpr size_t N=16384,C=262144,S=950300,P=131100;auto raw=readBlob(argv[1]);if(raw.size()!=8*S*sizeof(double))return 3;std::vector<double>all(raw.size()/8);memcpy(all.data(),raw.data(),raw.size());auto p=studyParams();auto pr=readBlob("study_input_pos_f32.bin"),vr=readBlob("study_input_vel_f32.bin");CPUState previous;for(auto*b:{&pr,&vr}){auto&dst=b==&pr?previous.pos:previous.vel;for(size_t i=0;i<b->size()/4;i++){float v;memcpy(&v,b->data()+4*i,4);dst.push_back(v);}}for(size_t step=0;step<8;step++){CPUState local=previous;cpuStep(local,p);const double*a=all.data()+step*S+P;std::vector<float4>pos(N),vel(N),rp(N),rv(N);std::vector<unsigned>keys(N),idx(N),starts(C),ends(C);size_t off=0;auto readV=[&](auto&dst){for(auto&v:dst){for(int k=0;k<4;k++){float value=a[off++];memcpy((char*)&v+4*k,&value,4);}}};readV(pos);readV(vel);for(auto*v:{&keys,&idx,&starts,&ends})for(auto&x:*v)x=(unsigned)a[off++];readV(rp);readV(rv);if(off!=819200)return 4;std::vector<double>expected=local.pos;expected.insert(expected.end(),local.vel.begin(),local.vel.end());expected.insert(expected.end(),local.prevel.begin(),local.prevel.end());auto check=checkState(pos,vel,rp,rv,keys,idx,starts,ends,expected,p);double position=0,velocity=0;size_t worst=0;for(size_t i=0;i<4*N;i++){position=std::max(position,fabs(a[i]-local.pos[i]));double d=fabs(a[4*N+i]-local.vel[i]);if(d>velocity){velocity=d;worst=i;}}std::vector<double>actualPre(4*N);for(size_t j=0;j<N;j++)for(int k=0;k<4;k++)actualPre[4*idx[j]+k]=((float*)&rv[j])[k];std::vector<double>forceExpected(a+4*N,a+8*N);double forceMax=0;const double cursor[4]={p.colliderPos.x,p.colliderPos.y,p.colliderPos.z,0},zero[4]={0,0,0,0};for(size_t i=0;i<N;i++){double f[3]={0,0,0};for(size_t j=0;j<N;j++)if(i!=j)sphereForce(a+4*i,a+4*j,actualPre.data()+4*i,actualPre.data()+4*j,p.particleRadius,p.particleRadius,p,f);sphereForce(a+4*i,cursor,actualPre.data()+4*i,zero,p.particleRadius,p.colliderRadius,p,f);for(int k=0;k<3;k++){forceExpected[4*i+k]=actualPre[4*i+k]+f[k];forceMax=std::max(forceMax,fabs(forceExpected[4*i+k]-a[4*N+4*i+k]));}}std::vector<double>actualCPU(a,a+8*N);actualCPU.insert(actualCPU.end(),actualPre.begin(),actualPre.end());auto structural=checkState(pos,vel,rp,rv,keys,idx,starts,ends,actualCPU,p);printf("{\"metadata_reorder_and_state_constraints_exact\":%s,\"force_residual_on_actual_gpu_integrated_positions_prevel\":%.17g,\"step\":%zu,\"one_step_from_actual_previous_float32_state\":true,\"all_exact_metadata_and_state_checks_pass\":%s,\"max_abs_position_residual\":%.17g,\"max_abs_velocity_residual\":%.17g,\"max_abs_all_continuous_residual\":%.17g,\"worst_velocity_particle_zero_based\":%zu,\"worst_velocity_axis\":%zu}\n",structural.ok?"true":"false",forceMax,step+1,check.ok?"true":"false",position,velocity,check.absolute,worst/4,worst%4);previous.pos.assign(a,a+4*N);previous.vel.assign(a+4*N,a+8*N);}}
